/// <summary>
/// insertEntityDataSource
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
/// <returns>boolean</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityContext, DataEntityDataSourceRuntimeContext _datasourceContext)
{
    boolean                      isValid;
    InventJournalTable           inventJournalTable;

    if (_datasourceContext.name() == dataEntityDataSourceStr(InventInventoryMovementJournalHeaderEntity, InventJournalTable))
    {
        inventJournalTable = _datasourceContext.getBuffer();
        if (!this.JournalNumber)
        {
            inventJournalTable.JournalId = JournalTableData::newTable(inventJournalTable).nextJournalId();
        }
    }

    isValid = next insertEntityDataSource(_entityContext, _datasourceContext);

    return isValid;
}
